const yen=v=>`${Math.round(Number(v||0)).toLocaleString('ja-JP')}円`;const num=(v,d=6)=>Number(v||0).toLocaleString('ja-JP',{minimumFractionDigits:d,maximumFractionDigits:d});const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function api(url,options={}){const response=await fetch(url,{...options,headers:{Accept:'application/json','Content-Type':'application/json',...(options.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error?.message||body.message||Object.values(body.errors||{}).flat()[0]||`通信エラー (${response.status})`);return body.data||body}
async function downloadReportExport(exportInfo){const response=await fetch(exportInfo.download_url,{credentials:'same-origin',headers:{Accept:exportInfo.mime_type||'application/octet-stream'}});if(!response.ok){const text=await response.text().catch(()=>'');throw new Error(text.slice(0,200)||`ダウンロードエラー (${response.status})`)}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=exportInfo.file_name||`tax-report.${exportInfo.format||'xlsx'}`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function canExport(){return canConfirm&&current?.status==='confirmed'}
function setExportBusy(format,busy){const button=document.getElementById(format==='pdf'?'export-pdf':'export-xlsx');if(button){button.disabled=busy||!canExport();button.textContent=busy?`${format.toUpperCase()}生成中...`:(format==='pdf'?'PDF確認表':'Excel確認表')}}
function message(text,error=false){const el=document.getElementById('page-message');el.textContent=text;el.className=`message${error?' error':''}`}
function initPeriod(){const now=new Date(),target=new Date(now.getFullYear(),now.getMonth()-1,1),year=document.getElementById('year'),month=document.getElementById('month');for(let y=target.getFullYear()-3;y<=target.getFullYear()+1;y++)year.add(new Option(`${y}年`,y));for(let m=1;m<=12;m++)month.add(new Option(`${m}月`,m));year.value=target.getFullYear();month.value=target.getMonth()+1}
function allSources(filing){return(filing?.lines||[]).flatMap(line=>(line.sources||[]).map(source=>({...source,category_name:line.liquor_tax_category_name})))}
function alcohol(v){return v==null||v===''?'-':`${Number(v)}度`}
function renderHistory(){document.getElementById('filing-list').innerHTML=filings.map(f=>`<button class="filing-item ${current?.id===f.id?'selected':''}" data-id="${f.id}"><span><strong>${f.year}年${f.month}月</strong><br><span class="subtle">${yen(f.net_payable_amount)}</span></span><span class="status ${f.status}">${f.status==='confirmed'?'確定':'下書き'}</span></button>`).join('')||'<div class="empty">申告履歴はありません</div>';document.querySelectorAll('.filing-item').forEach(b=>b.onclick=()=>{const filing=filings.find(f=>f.id===+b.dataset.id);if(!filing)return;document.getElementById('year').value=filing.year;document.getElementById('month').value=filing.month;loadDetail(filing.id)})}
function reset(){current=null;document.getElementById('summary-period').textContent='未作成';document.getElementById('summary-status').textContent='-';document.getElementById('summary-status').className='status';['summary-kl','summary-gross','summary-relief','summary-net'].forEach((id,i)=>document.getElementById(id).textContent=i===0?'0.000000 kl':'0円');document.getElementById('summary-warnings').textContent='警告 0件';document.getElementById('filing-lines').innerHTML='<tr><td colspan="9" class="empty">この月の下書きは未作成です</td></tr>';const create=document.getElementById('create');if(create){create.disabled=false;create.textContent='集計して下書き作成'}const reopen=document.getElementById('reopen');if(reopen)reopen.hidden=true;renderReliefBasis([]);renderSources([]);renderHistory()}
function renderFiling(f){current=f;document.getElementById('summary-period').textContent=`${f.year}年${f.month}月`;const st=document.getElementById('summary-status');st.textContent=f.status==='confirmed'?'確定':'下書き';st.className=`status ${f.status}`;document.getElementById('summary-kl').textContent=`${num(f.total_taxable_kl)} kl`;document.getElementById('summary-gross').textContent=yen(f.total_gross_tax_amount);document.getElementById('summary-relief').textContent=yen(Number(f.total_relief_amount)+Number(f.total_deduction_amount)-Number(f.total_adjustment_amount||0));document.getElementById('summary-net').textContent=yen(f.net_payable_amount);document.getElementById('summary-warnings').textContent=`警告 ${f.warning_count||0}件 / 調整 ${f.adjustment_count||0}件`;document.getElementById('rule-version').textContent=f.calculation_rule_version||'-';document.getElementById('relief-scheme').textContent=f.relief_scheme==='legacy_scheme'?'旧制度軽減':'新制度';document.getElementById('filing-lines').innerHTML=(f.lines||[]).map(x=>`<tr class="${x.requires_review?'review':''}"><td>${esc(x.liquor_tax_category_name||x.liquor_tax_category_code||'-')}</td><td>${esc(labels[x.tax_treatment]||x.tax_treatment||'-')}</td><td>${alcohol(x.reporting_alcohol_percentage)}</td><td class="num">${num(x.taxable_kl)}</td><td class="num">${Number(x.tax_per_kl||0).toLocaleString('ja-JP')}</td><td class="num">${yen(x.gross_tax_amount)}</td><td class="num">${yen(x.relief_amount)}</td><td class="num">${yen(x.deduction_amount)}</td><td class="num">${yen(x.net_tax_amount)}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">対象明細はありません</td></tr>';renderReliefBasis(f.lines||[]);renderSources(allSources(f));renderAdjustments(f);renderExports(f);document.getElementById('reconcile-shipments').textContent=`${f.shipment_count||0}件`;document.getElementById('reconcile-lines').textContent=`${f.line_count||0}件`;document.getElementById('reconcile-warnings').textContent=`${f.warning_count||0}件`;document.getElementById('reconcile-site').textContent=f.manufacturing_site_code||'-';document.getElementById('reconcile-scheme').textContent=f.relief_scheme==='legacy_scheme'?'旧制度軽減計算':'新制度計算';document.getElementById('reconcile-fy').textContent=f.fiscal_year||'-';const confirm=document.getElementById('confirm');if(confirm)confirm.disabled=!canConfirm||f.status==='confirmed';const reopen=document.getElementById('reopen');if(reopen)reopen.hidden=!canConfirm||!f.can_reopen;const create=document.getElementById('create');if(create){create.disabled=f.status!=='draft';create.textContent=f.status==='draft'?'下書きを再集計':'確定取消後に再集計'}['export-xlsx','export-pdf'].forEach(id=>document.getElementById(id).disabled=!canExport());renderHistory()}
function renderReliefBasis(lines){const rows=lines.filter(x=>x.relief_calculation_basis);document.getElementById('relief-basis-count').textContent=`${rows.length}件`;document.getElementById('relief-basis-lines').innerHTML=rows.map(x=>{const b=x.relief_calculation_basis||{},segments=b.segments||[];const detail=b.scheme==='new_scheme'?(segments.map(s=>`${bandLabel(s.band)} ${yen(s.tax_base_amount)} × ${percent(s.rate)}`).join(' / ')||'軽減対象帯なし'):`対象 ${num(b.eligible_kl_before)}→${num(b.eligible_kl_after)} kl / ${percent(b.reduction_rate)}`;const result=b.direction==='reverse'?b.reversed_relief_amount:x.relief_amount;return `<tr><td>${x.line_no}</td><td>${esc(x.liquor_tax_category_name||'-')}</td><td>${esc(labels[x.tax_treatment]||x.tax_treatment)}</td><td>${alcohol(x.reporting_alcohol_percentage)}</td><td class="num">${x.cumulative_gross_before==null?'-':yen(x.cumulative_gross_before)}</td><td class="num">${x.cumulative_gross_after==null?'-':yen(x.cumulative_gross_after)}</td><td>${esc(b.rate_column||'旧制度')}</td><td>${esc(detail)}</td><td class="num">${yen(result)}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty">計算根拠はありません</td></tr>'}
const bandLabel=band=>({up_to_50m:'5,000万円以下','50m_to_80m':'5,000万超～8,000万円','80m_to_100m':'8,000万超～1億円',over_100m:'1億円超'}[band]||band);const percent=rate=>`${Number(rate||0)*100}%`;
function renderAdjustments(f){const rows=f.adjustments||[];document.getElementById('adjustment-count').textContent=`${rows.filter(x=>x.status==='active').length}件`;document.getElementById('adjustment-lines').innerHTML=rows.map(x=>`<tr class="${x.status==='voided'?'subtle':''}"><td>${x.line_no}</td><td>${esc(x.adjustment_type)}</td><td>${esc(x.liquor_tax_category_name||'-')}</td><td class="num">${num(x.taxable_kl_adjustment)}</td><td class="num">${yen(x.tax_amount_adjustment)}</td><td>${esc(x.description)}</td><td>${x.approval_required?`<span class="status ${x.approval_status==='approved'?'confirmed':'draft'}">${esc(x.approval_status||'未申請')}</span>${canApprove&&x.approval_status==='pending'?` <button data-approve="${x.approval_request_id}">承認</button>`:''}`:'不要'}</td><td>${canCreate&&f.status==='draft'&&x.status==='active'?`<button class="danger" data-void="${x.id}">取消</button>`:esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">調整はありません</td></tr>';const form=document.getElementById('adjustment-form');if(form)form.hidden=f.status!=='draft';const category=document.getElementById('adjustment-category');if(category){const selected=category.value;category.innerHTML='<option value="">指定なし</option>'+[...new Map((f.lines||[]).filter(x=>x.liquor_tax_category_id).map(x=>[x.liquor_tax_category_id,x])).values()].map(x=>`<option value="${x.liquor_tax_category_id}">${esc(x.liquor_tax_category_name)}</option>`).join('');category.value=selected}document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approveAdjustment(+b.dataset.approve));document.querySelectorAll('[data-void]').forEach(b=>b.onclick=()=>voidAdjustment(+b.dataset.void))}
function renderExports(f){document.getElementById('export-list').innerHTML=(f.report_exports||[]).map(x=>`<a class="filing-item" href="${x.download_url}"><span><strong>${x.format.toUpperCase()} ${esc(x.file_name)}</strong><br><span class="subtle">${esc(x.reason||'')} / ${esc(x.generated_at||'')}</span></span><span>${Math.ceil(x.file_size/1024).toLocaleString()} KB</span></a>`).join('')||'<div class="empty">出力履歴はありません</div>'}
function renderSources(sources){document.getElementById('source-count').textContent=`${sources.length}件`;document.getElementById('source-lines').innerHTML=sources.map(x=>`<tr class="${x.requires_review?'review':''}"><td>${esc(x.source_date||'-')}</td><td class="source-doc">${esc(x.source_document_number||'-')}</td><td>${esc(sourceLabels[x.source_type]||x.source_type)}</td><td>${esc(labels[x.tax_treatment]||x.tax_treatment)}</td><td>${alcohol(x.reporting_alcohol_percentage)}</td><td class="num">${num(x.quantity,3)}</td><td class="num">${num(x.taxable_kl)}</td><td class="num">${yen(x.gross_tax_amount)}</td><td>${x.requires_review?'<span class="source-review">要確認</span>':'済'}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">根拠データはありません</td></tr>';const exceptions=sources.filter(x=>x.requires_review);document.getElementById('exception-count').textContent=`${exceptions.length}件`;document.getElementById('exception-notice').hidden=!exceptions.length;document.getElementById('exception-lines').innerHTML=exceptions.map(x=>{const shipment=['shipment','shipment_lot'].includes(x.source_type)&&['export_exempt','untaxed_transfer'].includes(x.tax_treatment);const returned=x.source_type==='sales_return';const action=canCreate&&current?.status==='draft'&&shipment?`<button data-evidence="${x.source_header_id}">証明確認</button>`:canCreate&&current?.status==='draft'&&returned?`<button data-return-review="${x.source_line_id}">戻入判定</button>`:'-';return `<tr class="review"><td>${esc(x.source_date||'-')}</td><td class="source-doc">${esc(x.source_document_number||'-')}</td><td>${esc(labels[x.tax_treatment]||x.tax_treatment)}</td><td>${esc(x.review_reason||'税務区分を確認してください')}</td><td class="num">${num(x.quantity,3)}</td><td>${action}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">例外はありません</td></tr>';document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>openEvidenceDialog(+b.dataset.evidence));document.querySelectorAll('[data-return-review]').forEach(b=>b.onclick=()=>openReturnDialog(+b.dataset.returnReview))}
function openEvidenceDialog(id){document.getElementById('evidence-shipment-id').value=id;document.getElementById('evidence-status').value='confirmed';document.getElementById('evidence-date').value=new Date().toISOString().slice(0,10);['evidence-reference','evidence-destination','evidence-customs','evidence-note'].forEach(x=>document.getElementById(x).value='');document.getElementById('evidence-exporter').value='';document.getElementById('evidence-dialog').showModal()}
function openReturnDialog(id){document.getElementById('return-line-id').value=id;document.getElementById('return-treatment').value='eligible';document.getElementById('return-reason').value='';document.getElementById('return-dialog').showModal()}
async function rebuildAfterException(){await api('/api/v1/tax/liquor-monthly-filings',{method:'POST',body:JSON.stringify({year:current.year,month:current.month,reason:'例外取引確認後の再集計'})});await loadList()}
async function loadDetail(id,listToken=null){const request=++detailRequestId;try{message('');const d=await api(`/api/v1/tax/liquor-monthly-filings/${id}`);if(request!==detailRequestId||(listToken!==null&&listToken!==listRequestId))return;renderFiling(d.liquor_tax_monthly_filing)}catch(e){if(request===detailRequestId)message(e.message,true)}}
async function loadList(){const request=++listRequestId;detailRequestId++;listLoading=true;current=null;const create=document.getElementById('create');if(create){create.disabled=true;create.textContent='読込中...'}const year=+document.getElementById('year').value,month=+document.getElementById('month').value;try{message('');const d=await api('/api/v1/tax/liquor-monthly-filings');if(request!==listRequestId)return;filings=d.liquor_tax_monthly_filings||[];const found=filings.find(f=>f.year===year&&f.month===month);if(found)await loadDetail(found.id,request);else reset()}catch(e){if(request===listRequestId)message(e.message,true)}finally{if(request===listRequestId)listLoading=false}}
function renderSettings(data){const rows=data.liquor_tax_relief_settings||[];document.getElementById('relief-setting-lines').innerHTML=rows.map(x=>`<tr><td>${esc(x.effective_from)} ～ ${esc(x.effective_to||'継続中')}</td><td><span class="status ${x.scheme==='new_scheme'?'draft':'confirmed'}">${x.scheme==='new_scheme'?'新制度':'旧制度'}</span></td><td>${esc(x.calculation_rule_version)}</td><td class="num">${x.prior_year_total_taxable_quantity_kl==null?'-':num(x.prior_year_total_taxable_quantity_kl)}</td><td class="num">${x.prior_year_peak_taxable_quantity_kl==null?'-':num(x.prior_year_peak_taxable_quantity_kl)}</td><td>${esc([x.approval_date,x.approval_reference,x.discontinuance_notice_date].filter(Boolean).join(' / ')||'-')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">設定がありません</td></tr>';const threshold=data.liquor_tax_adjustment_setting||{};document.getElementById('threshold-amount').value=threshold.approval_amount_threshold||0;document.getElementById('threshold-kl').value=threshold.approval_quantity_threshold_kl||0;document.getElementById('threshold-active').value=threshold.is_active===false?'0':'1';if(canManageSettings){const migrated=rows.some(x=>x.scheme==='new_scheme');const legacyOption=document.querySelector('#setting-scheme option[value="legacy_scheme"]');legacyOption.disabled=migrated;if(migrated)document.getElementById('setting-scheme').value='new_scheme';toggleSchemeFields();setSuggestedEffectiveDate(rows)}}
function toggleSchemeFields(){if(!canManageSettings)return;const isNew=document.getElementById('setting-scheme').value==='new_scheme';document.querySelectorAll('.new-setting').forEach(x=>x.hidden=!isNew);document.querySelectorAll('.legacy-setting').forEach(x=>x.hidden=isNew);document.getElementById('scheme-warning').hidden=!isNew}
function setSuggestedEffectiveDate(rows){const input=document.getElementById('setting-effective-from');if(input.value)return;const now=new Date(),year=now.getMonth()>=3?now.getFullYear()+1:now.getFullYear();input.value=`${year}-04-01`;const latest=rows[0];if(latest?.effective_from&&input.value<=latest.effective_from)input.value=`${Number(latest.effective_from.slice(0,4))+1}-04-01`}
async function loadSettings(force=false){if(settingsLoaded&&!force)return;try{const data=await api('/api/v1/tax/liquor-settings');renderSettings(data);settingsLoaded=true}catch(e){message(e.message,true)}}
document.querySelectorAll('.tab').forEach(tab=>tab.onclick=()=>{document.querySelectorAll('.tab,.panel').forEach(x=>x.classList.remove('active'));tab.classList.add('active');document.getElementById(`panel-${tab.dataset.panel}`).classList.add('active');if(tab.dataset.panel==='settings')loadSettings()});document.getElementById('reload').onclick=loadList;document.getElementById('year').onchange=loadList;document.getElementById('month').onchange=loadList;
document.getElementById('create')?.addEventListener('click',async()=>{const button=document.getElementById('create'),year=+document.getElementById('year').value,month=+document.getElementById('month').value;if(listLoading)return message('対象月を読み込み中です。完了後に再度実行してください。',true);const selected=filings.find(f=>f.year===year&&f.month===month);if(selected?.status!=='draft')return message('確定済み申告は、先に「確定を取り消して書き直す」で下書きに戻してください。',true);if(selected&&current?.id!==selected.id){await loadDetail(selected.id);return message('対象月の最新状態を読み込みました。内容を確認して再度実行してください。',true)}try{button.disabled=true;const reason=selected?'送信前の再集計':'月次申告下書きの初回集計';await api('/api/v1/tax/liquor-monthly-filings',{method:'POST',body:JSON.stringify({year,month,reason})});await loadList();message(selected?'下書きを再集計しました。':'月次申告の下書きを作成しました。')}catch(e){await loadList();message(e.message,true)}finally{button.disabled=listLoading||Boolean(current&&current.status!=='draft')}});
document.getElementById('confirm')?.addEventListener('click',async()=>{if(!current)return message('確定する下書きがありません。',true);const reason=document.getElementById('confirm-reason').value.trim();if(!reason)return message('確認・確定理由を入力してください。',true);const button=document.getElementById('confirm');try{button.disabled=true;await api(`/api/v1/tax/liquor-monthly-filings/${current.id}/confirm`,{method:'POST',body:JSON.stringify({reason})});document.getElementById('confirm-reason').value='';message('申告値を確定しました。');await loadDetail(current.id)}catch(e){message(e.message,true)}finally{button.disabled=current?.status==='confirmed'}});
document.getElementById('reopen')?.addEventListener('click',async()=>{if(!current?.can_reopen)return message('下書きに戻せるのは最新の確定済み申告だけです。',true);const reason=document.getElementById('confirm-reason').value.trim();if(!reason)return message('確定を取り消す理由を入力してください。',true);if(!window.confirm(`${current.year}年${current.month}月分の確定を取り消し、下書きに戻しますか？`))return;const button=document.getElementById('reopen');try{button.disabled=true;await api(`/api/v1/tax/liquor-monthly-filings/${current.id}/reopen`,{method:'POST',body:JSON.stringify({reason})});document.getElementById('confirm-reason').value='';message('確定時の内容を履歴に保存し、下書きに戻しました。再集計して書き直せます。');await loadList();await loadDetail(current.id)}catch(e){message(e.message,true)}finally{button.disabled=false}});
document.getElementById('add-adjustment')?.addEventListener('click',async()=>{if(!current)return;const description=document.getElementById('adjustment-description').value.trim();if(!description)return message('調整の根拠・理由を入力してください。',true);try{await api(`/api/v1/tax/liquor-monthly-filings/${current.id}/adjustments`,{method:'POST',body:JSON.stringify({adjustment_type:document.getElementById('adjustment-type').value,liquor_tax_category_id:document.getElementById('adjustment-category').value||null,taxable_kl_adjustment:document.getElementById('adjustment-kl').value,tax_amount_adjustment:document.getElementById('adjustment-amount').value,description})});document.getElementById('adjustment-description').value='';message('調整明細を追加し、必要な承認依頼を作成しました。');await loadDetail(current.id)}catch(e){message(e.message,true)}});
async function approveAdjustment(id){try{await api(`/api/v1/approval-requests/${id}/approve`,{method:'POST',body:JSON.stringify({comment:'酒税申告の調整内容を確認'})});message('調整明細を承認しました。');await loadDetail(current.id)}catch(e){message(e.message,true)}}
async function voidAdjustment(id){const reason=prompt('取消理由を入力してください。');if(!reason)return;try{await api(`/api/v1/tax/liquor-monthly-filings/${current.id}/adjustments/${id}/void`,{method:'POST',body:JSON.stringify({reason})});message('調整明細を取消しました。');await loadDetail(current.id)}catch(e){message(e.message,true)}}
async function createExport(format){if(!current)return message('確定済みの申告データを選択してください。',true);if(!canExport())return message('確認表を出力する権限、または確定済み申告がありません。',true);const reason=document.getElementById('confirm-reason').value.trim()||'e-Tax転記用確認表';try{setExportBusy(format,true);message(`${format.toUpperCase()}確認表を生成中です...`);const d=await api(`/api/v1/tax/liquor-monthly-filings/${current.id}/exports`,{method:'POST',body:JSON.stringify({format,reason})});message(`${format.toUpperCase()}確認表をダウンロードしています...`);await downloadReportExport(d.report_export);message(`${format.toUpperCase()}確認表を生成しました。ダウンロードが始まらない場合は、下の出力履歴から開いてください。`);await loadDetail(current.id)}catch(e){message(e.message,true)}finally{setExportBusy(format,false)}}
document.getElementById('export-xlsx')?.addEventListener('click',()=>createExport('xlsx'));document.getElementById('export-pdf')?.addEventListener('click',()=>createExport('pdf'));
document.getElementById('save-evidence').onclick=async e=>{e.preventDefault();const id=document.getElementById('evidence-shipment-id').value;try{await api(`/api/v1/tax/shipments/${id}/liquor-tax-evidence`,{method:'PUT',body:JSON.stringify({status:document.getElementById('evidence-status').value,evidence_reference:document.getElementById('evidence-reference').value||null,evidence_date:document.getElementById('evidence-date').value||null,destination:document.getElementById('evidence-destination').value||null,customs_office:document.getElementById('evidence-customs').value||null,exporter_type:document.getElementById('evidence-exporter').value||null,note:document.getElementById('evidence-note').value||null})});document.getElementById('evidence-dialog').close();message('証明状態を保存しました。');await rebuildAfterException()}catch(error){message(error.message,true)}};
document.getElementById('save-return-review').onclick=async e=>{e.preventDefault();const id=document.getElementById('return-line-id').value;const reason=document.getElementById('return-reason').value.trim();if(!reason)return message('戻入判定の理由を入力してください。',true);try{await api(`/api/v1/tax/sales-return-lines/${id}/liquor-tax-treatment`,{method:'PUT',body:JSON.stringify({treatment:document.getElementById('return-treatment').value,reason})});document.getElementById('return-dialog').close();message('戻入判定を保存しました。');await rebuildAfterException()}catch(error){message(error.message,true)}};
document.getElementById('setting-scheme')?.addEventListener('change',toggleSchemeFields);
document.getElementById('save-relief-setting')?.addEventListener('click',async()=>{const scheme=document.getElementById('setting-scheme').value,reason=document.getElementById('setting-reason').value.trim();if(!reason)return message('計算方式の変更理由を入力してください。',true);const payload={scheme,effective_from:document.getElementById('setting-effective-from').value,opening_gross_tax_amount:document.getElementById('setting-opening-gross').value||0,note:document.getElementById('setting-note').value||null,reason};if(scheme==='legacy_scheme'){payload.legacy_reduction_rate=document.getElementById('setting-legacy-rate').value;payload.legacy_annual_quantity_limit_kl=document.getElementById('setting-legacy-limit').value}else{payload.prior_year_total_taxable_quantity_kl=document.getElementById('setting-prior-total').value;payload.prior_year_peak_taxable_quantity_kl=document.getElementById('setting-prior-peak').value;payload.approval_date=document.getElementById('setting-approval-date').value;payload.approval_reference=document.getElementById('setting-approval-reference').value;payload.discontinuance_notice_date=document.getElementById('setting-discontinuance-date').value||null}try{await api('/api/v1/tax/liquor-settings/relief-periods',{method:'POST',body:JSON.stringify(payload)});message('軽減計算方式の適用期間を追加しました。');settingsLoaded=false;await loadSettings(true)}catch(e){message(e.message,true)}});
document.getElementById('save-thresholds')?.addEventListener('click',async()=>{const reason=document.getElementById('threshold-reason').value.trim();if(!reason)return message('承認基準の変更理由を入力してください。',true);try{await api('/api/v1/tax/liquor-settings/adjustment-thresholds',{method:'PUT',body:JSON.stringify({approval_amount_threshold:document.getElementById('threshold-amount').value,approval_quantity_threshold_kl:document.getElementById('threshold-kl').value,is_active:document.getElementById('threshold-active').value==='1',reason})});message('調整明細の承認基準を保存しました。');settingsLoaded=false;await loadSettings(true)}catch(e){message(e.message,true)}});
initPeriod();loadList();
</script>
</body>
</html>
